function mirrorAndInvert(grid: number[][]): number[][] {
  for (const row of grid) {
    let i = 0, j = row.length - 1;
    while (i < j) {
      // a differing pair is unchanged by mirror + invert
      if (row[i] === row[j]) {
        row[i] ^= 1;
        row[j] ^= 1;
      }
      i++;
      j--;
    }
    if (i === j) row[i] ^= 1;
  }
  return grid;
}

